const PLANTS=[
 {id:'snake',name:'Snake Plant',latin:'Dracaena trifasciata',icon:'🌿',tint:'#dce9cc',difficulty:'Easy',space:'Small',sun:'low',sunLabel:'Low–bright',water:14,max:18,maintenance:'low',wind:'moderate'},
 {id:'jade',name:'Jade Plant',latin:'Crassula ovata',icon:'🪴',tint:'#d7eddb',difficulty:'Easy',space:'Small',sun:'high',sunLabel:'Bright sun',water:12,max:16,maintenance:'low',wind:'windy'},
 {id:'pothos',name:'Golden Pothos',latin:'Epipremnum aureum',icon:'🍃',tint:'#e9efc8',difficulty:'Easy',space:'Small',sun:'medium',sunLabel:'Indirect',water:7,max:10,maintenance:'low',wind:'sheltered'},
 {id:'rubber',name:'Rubber Plant',latin:'Ficus elastica',icon:'🌱',tint:'#e1d9ce',difficulty:'Moderate',space:'Medium',sun:'medium',sunLabel:'Bright indirect',water:8,max:11,maintenance:'medium',wind:'sheltered'},
 {id:'areca',name:'Areca Palm',latin:'Dypsis lutescens',icon:'🌴',tint:'#d9edcf',difficulty:'Moderate',space:'Large',sun:'medium',sunLabel:'Filtered sun',water:5,max:7,maintenance:'high',wind:'sheltered'},
 {id:'aloe',name:'Aloe Vera',latin:'Aloe barbadensis',icon:'🌵',tint:'#d9ece5',difficulty:'Easy',space:'Small',sun:'high',sunLabel:'Bright sun',water:16,max:21,maintenance:'low',wind:'windy'},
 {id:'basil',name:'Holy Basil',latin:'Ocimum tenuiflorum',icon:'☘️',tint:'#e6efd6',difficulty:'Moderate',space:'Small',sun:'high',sunLabel:'4–6 hrs sun',water:2,max:3,maintenance:'high',wind:'moderate'},
 {id:'zz',name:'ZZ Plant',latin:'Zamioculcas zamiifolia',icon:'🌿',tint:'#d8e8d7',difficulty:'Easy',space:'Medium',sun:'low',sunLabel:'Low–indirect',water:18,max:24,maintenance:'low',wind:'sheltered'},
 {id:'spider',name:'Spider Plant',latin:'Chlorophytum comosum',icon:'🌱',tint:'#e5edda',difficulty:'Easy',space:'Small',sun:'medium',sunLabel:'Bright indirect',water:7,max:10,maintenance:'low',wind:'moderate'},
 {id:'peace-lily',name:'Peace Lily',latin:'Spathiphyllum',icon:'🪴',tint:'#e2eadf',difficulty:'Moderate',space:'Medium',sun:'low',sunLabel:'Shade–indirect',water:5,max:7,maintenance:'medium',wind:'sheltered'},
 {id:'monstera',name:'Monstera',latin:'Monstera deliciosa',icon:'🍃',tint:'#d6e7d2',difficulty:'Moderate',space:'Large',sun:'medium',sunLabel:'Bright indirect',water:8,max:11,maintenance:'medium',wind:'sheltered'},
 {id:'bougainvillea',name:'Bougainvillea',latin:'Bougainvillea glabra',icon:'🌺',tint:'#f1dce2',difficulty:'Moderate',space:'Large',sun:'high',sunLabel:'Full sun',water:6,max:9,maintenance:'medium',wind:'windy'},
 {id:'curry-leaf',name:'Curry Leaf',latin:'Murraya koenigii',icon:'🌿',tint:'#ddebd4',difficulty:'Moderate',space:'Medium',sun:'high',sunLabel:'4–6 hrs sun',water:4,max:6,maintenance:'medium',wind:'moderate'},
 {id:'mint',name:'Mint',latin:'Mentha',icon:'☘️',tint:'#d9efdf',difficulty:'Moderate',space:'Small',sun:'medium',sunLabel:'Gentle sun',water:2,max:3,maintenance:'high',wind:'moderate'},
 {id:'rosemary',name:'Rosemary',latin:'Salvia rosmarinus',icon:'🌾',tint:'#e0e7d8',difficulty:'Moderate',space:'Small',sun:'high',sunLabel:'Full sun',water:7,max:10,maintenance:'medium',wind:'windy'},
 {id:'boston-fern',name:'Boston Fern',latin:'Nephrolepis exaltata',icon:'🌿',tint:'#d8eadc',difficulty:'Fussy',space:'Medium',sun:'low',sunLabel:'Filtered shade',water:3,max:4,maintenance:'high',wind:'sheltered'},
 {id:'aglaonema',name:'Chinese Evergreen',latin:'Aglaonema',icon:'🍃',tint:'#e4e8d8',difficulty:'Easy',space:'Medium',sun:'low',sunLabel:'Low–indirect',water:10,max:14,maintenance:'low',wind:'sheltered'}
];
const state={step:1,profile:{},selected:[],departure:'',returnDate:'',duration:0,assessment:[],foster:'Home visit',showAll:false,user:null};
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function save(){localStorage.setItem('plantstay-state',JSON.stringify(state))}
function makeGuest(){const id=(globalThis.crypto?.randomUUID?.()||Math.random().toString(36).slice(2)).replaceAll('-','').slice(0,6).toUpperCase();return{id,createdAt:new Date().toISOString()}}
function showStep(n){state.step=n;const hasPlan=state.assessment.length>0&&state.duration>0;$$('.panel').forEach(p=>p.classList.toggle('active',+p.dataset.panel===n));$$('.step').forEach(s=>s.classList.toggle('active',+s.dataset.step===n));$('[data-panel="4"]').classList.toggle('needs-plan',!hasPlan);$('#carePlanEmpty').hidden=hasPlan;updateGardenUI();save();scrollTo({top:$('.workspace').offsetTop-90,behavior:'smooth'})}
function profile(){return{city:$('#city').value.trim(),direction:$('input[name=direction]:checked').value,sunlight:$('#sunlight').value,size:$('#size').value,wind:$('#wind').value,maintenance:$('#maintenance').value}}
function showBalconyPreview(file){const reader=new FileReader();reader.onload=()=>{$('#balconyPreview').innerHTML=`<img src="${reader.result}" alt="Balcony preview" /><small>${file.name}</small>`;$('#scanBalcony').disabled=false};reader.readAsDataURL(file)}
function profileBasedBalconyInsight(){const p=profile();const light={low:'lower-light corners and filtered shade',medium:'bright indirect areas with a few hours of gentle sun',high:'sunny edges and direct-light zones'}[p.sunlight];const wind={sheltered:'a protected setup',moderate:'some shelter for delicate leaves',windy:'wind-tolerant plants kept away from the strongest edge'}[p.wind];return{title:`A ${p.direction.toLowerCase()}-facing balcony in ${p.city||'your city'}`,summary:`Your current profile points to ${light}, with ${wind}. Keep the photo-based reading as a starting point and confirm the sunlight across a full day.`,bullets:[`Prioritize ${p.size} plants so the space stays easy to move and water.`,`Use the brightest stable zone for sun-loving plants; keep shade plants farther from the edge.`,`Before travel, group pots where they get consistent light and less wind.`]}}
async function analyzeBalcony(){const file=$('#balconyPhoto').files?.[0];if(!file)return;const result=$('#balconyResult');const button=$('#scanBalcony');button.disabled=true;button.innerHTML='Reading your balcony <span class="scan-pulse">✦</span>';result.hidden=false;result.innerHTML='<div class="scan-loading">Looking for light, edges, and sheltered zones…</div>';try{const response=await fetch('/api/analyze-balcony',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({city:$('#city').value.trim(),profile:profile(),imageName:file.name})});if(!response.ok)throw new Error('AI route unavailable');const data=await response.json();result.innerHTML=`<p class="section-kicker">GEMINI BALCONY READ</p><h4>${data.title}</h4><p>${data.summary}</p><ul>${(data.bullets||[]).map(b=>`<li>${b}</li>`).join('')}</ul>`}catch{const data=profileBasedBalconyInsight();result.innerHTML=`<p class="section-kicker">PROFILE-BASED PREVIEW</p><h4>${data.title}</h4><p>${data.summary}</p><ul>${data.bullets.map(b=>`<li>${b}</li>`).join('')}</ul><small class="scan-note">Gemini photo analysis will plug into this same result card once the secure server route is connected.</small>`}finally{button.disabled=false;button.innerHTML='Analyze again <span>✦</span>'}}
function scorePlant(p){let s=68;const pr=state.profile;s+=p.sun===pr.sunlight?16:(p.sun==='medium'||pr.sunlight==='medium'?8:-5);s+=p.maintenance===pr.maintenance?8:(p.maintenance==='low'?5:0);if(pr.size==='compact'&&p.space==='Large')s-=18;if(pr.wind==='windy'&&p.wind==='sheltered')s-=8;return Math.max(54,Math.min(98,s))}
function normaliseSelection(){state.selected=[...new Set(Array.isArray(state.selected)?state.selected:[])].filter(id=>PLANTS.some(p=>p.id===id))}
function renderPlants(){normaliseSelection();const ranked=[...PLANTS].sort((a,b)=>scorePlant(b)-scorePlant(a));const visible=state.showAll?ranked:ranked.slice(0,5);$('#recommendations').innerHTML=visible.map(p=>{const selected=state.selected.includes(p.id);return`<article class="plant-card ${selected?'selected':''}" style="--tint:${p.tint}"><span class="match">${scorePlant(p)}% match</span><div class="plant-top"><span class="plant-glyph">${p.icon}</span><div><h3>${p.name}</h3><span class="latin">${p.latin}</span></div></div><div class="plant-facts"><div class="fact"><small>Care</small><b>${p.difficulty}</b></div><div class="fact"><small>Space</small><b>${p.space}</b></div><div class="fact"><small>Light</small><b>${p.sunLabel}</b></div><div class="fact"><small>Water</small><b>Every ${p.water} days</b></div><div class="fact"><small>Alone for</small><b>Up to ${p.max} days</b></div></div><button class="add-plant" type="button" data-id="${p.id}" aria-pressed="${selected}">${selected?'✓ Added · click to remove':'+ Add to my garden'}</button></article>`}).join('');$('#exploreToggle').textContent=state.showAll?'Show top 5 matches ↑':`Explore all ${PLANTS.length} plants ↓`;updateGardenUI()}
function updateGardenUI(){normaliseSelection();const count=state.selected.length;$('#selectedCount').textContent=count;$('#headerGardenCount').textContent=count;$('#clearGarden').hidden=count===0;$('#gardenEmpty').hidden=count>0;$('#gardenNext').disabled=!count;$('#tripPrereq').hidden=count>0;$('#buildPlanButton').disabled=!count;$('#tripPlants').innerHTML=state.selected.map(id=>{const p=PLANTS.find(x=>x.id===id);return`<div class="trip-plant"><span>${p.icon} <b>${p.name}</b></span><small>every ${p.water}d</small></div>`}).join('')}
function updateDuration(){const a=new Date($('#departure').value+'T12:00:00'),b=new Date($('#returnDate').value+'T12:00:00');if(!$('#departure').value||!$('#returnDate').value){state.duration=0;$('#durationValue').textContent='—';$('#durationNote').textContent='Choose both dates';return}const d=Math.round((b-a)/86400000);state.duration=d>0?d:0;$('#durationValue').textContent=d>0?d:'—';$('#durationNote').textContent=d===1?'One night away':d>1?`${d-1} nights away`:'Return must be later';$('#dateError').textContent=d<=0?'Return date must be after departure.':''}
function classify(p,d){if(d<=p.max*.7)return{label:'Safe Alone',key:'safe',prep:'Water deeply before leaving; no visit needed.'};if(d<=p.max)return{label:'Prepare Before Leaving',key:'prepare',prep:'Deep water, mulch lightly, and move out of harsh afternoon sun.'};if(d<=p.max+p.water)return{label:'Needs One Visit',key:'visit',prep:`Ask for one measured watering around day ${Math.min(p.max,d-1)}.`};return{label:'Needs Multiple Visits',key:'multi',prep:`Arrange watering every ${p.water} days while you’re away.`}}
function fmt(date,opts={month:'short',day:'numeric'}){return new Intl.DateTimeFormat('en-IN',opts).format(new Date(date+'T12:00:00'))}
function addDays(date,n){const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)}
function buildResults(){const d=state.duration;state.assessment=state.selected.map(id=>{const plant=PLANTS.find(p=>p.id===id);return{plant,...classify(plant,d)}});const counts={safe:0,prepare:0,visit:0,multi:0};state.assessment.forEach(a=>counts[a.key]++);const ready=Math.round(((counts.safe+counts.prepare*.8+counts.visit*.55+counts.multi*.3)/state.assessment.length)*100);$('#readinessScore').textContent=ready+'%';$('#tripSummary').textContent=`${state.profile.city} · ${fmt(state.departure)}–${fmt(state.returnDate)} · ${d} days`;
 $('#assessmentSummary').innerHTML=[['safe','Safe alone'],['prepare','Prep only'],['visit','One visit'],['multi','Multiple visits']].map(([k,l])=>`<div class="summary-pill"><b>${counts[k]}</b><small>${l}</small></div>`).join('');
 const colors={safe:['#e6f4ec','#287b55'],prepare:['#fff1d6','#9b6617'],visit:['#fae6df','#ae4a32'],multi:['#f8dfe3','#8f3340']};
 $('#assessments').innerHTML=state.assessment.map(a=>`<article class="assessment"><div class="assessment-plant"><span>${a.plant.icon}</span><span>${a.plant.name}</span></div><span class="status-badge" style="--status-bg:${colors[a.key][0]};--status:${colors[a.key][1]}">${a.label}</span><p>${a.prep}</p></article>`).join('');
 renderTimeline();renderPassport();save();showStep(4)}
function renderTimeline(){let tasks=[{date:addDays(state.departure,-1),title:'Prep the whole garden',text:'Water deeply, remove dry leaves, and group pots away from harsh edges.'},{date:state.departure,title:'Final morning check',text:'Empty saucers, check drainage, and keep the care passport handy.'}];state.assessment.forEach(a=>{if(a.key==='visit')tasks.push({date:addDays(state.departure,Math.min(a.plant.max,state.duration-1)),title:`Water ${a.plant.name}`,text:'Check the topsoil first. Water slowly only if dry.'});if(a.key==='multi')for(let n=a.plant.water;n<state.duration;n+=a.plant.water)tasks.push({date:addDays(state.departure,n),title:`Water ${a.plant.name}`,text:'Give a measured drink; do not leave the pot standing in water.'})});tasks.push({date:state.returnDate,title:'Welcome-home check',text:'Inspect leaves and soil before watering. Return plants to their usual spots gradually.'});tasks.sort((a,b)=>a.date.localeCompare(b.date));$('#timeline').innerHTML=tasks.map(t=>`<div class="timeline-item"><span class="timeline-date">${fmt(t.date)}</span><span class="timeline-dot"></span><div class="timeline-content"><b>${t.title}</b><p>${t.text}</p></div></div>`).join('')}
function passportText(){const visits=state.assessment.filter(a=>['visit','multi'].includes(a.key));return`PLANTSTAY CARE PASS\n${state.profile.city} · ${fmt(state.departure)}–${fmt(state.returnDate)}\nCare arrangement: ${state.foster}\n\n${state.assessment.map(a=>`${a.plant.name}: ${a.label} — ${a.prep}`).join('\n')}\n\nGeneral note: Check soil before watering. Please do not leave pots sitting in water.`}
function renderPassport(){const visits=state.assessment.filter(a=>['visit','multi'].includes(a.key));$('#passportDates').textContent=`${fmt(state.departure)}—${fmt(state.returnDate)}`;$('#passportTitle').textContent=`Care notes for ${state.profile.city}`;$('#passportBody').innerHTML=`<div class="passport-line"><b>Plants</b><span>${state.assessment.map(a=>a.plant.name).join(', ')}</span></div><div class="passport-line"><b>Visits</b><span>${visits.length?visits.map(a=>a.label==='Needs One Visit'?`1 for ${a.plant.name}`:`Every ${a.plant.water} days for ${a.plant.name}`).join('; '):'None needed'}</span></div><div class="passport-line"><b>Setup</b><span>${state.foster}</span></div><div class="passport-line"><b>Rule</b><span>Check soil first. Water only when the top layer feels dry.</span></div>`}
function loadDemo(){const leave=new Date();leave.setDate(leave.getDate()+6);const ret=new Date(leave);ret.setDate(ret.getDate()+12);const iso=d=>d.toISOString().slice(0,10);Object.assign(state,{profile:{city:'Bengaluru',direction:'East',sunlight:'medium',size:'medium',wind:'moderate',maintenance:'medium'},selected:['snake','pothos','rubber','areca'],departure:iso(leave),returnDate:iso(ret),duration:12,foster:'Home visit'});hydrate();renderPlants();buildResults();toast('Demo trip loaded')}
function hydrate(){if(state.profile.city){$('#city').value=state.profile.city;const r=$(`input[name=direction][value="${state.profile.direction}"]`);if(r)r.checked=true;['sunlight','size','wind','maintenance'].forEach(k=>{if(state.profile[k])$('#'+k).value=state.profile[k]})}$('#departure').value=state.departure||'';$('#returnDate').value=state.returnDate||'';updateDuration();updateGardenUI()}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
$('#profileForm').addEventListener('submit',e=>{e.preventDefault();const city=$('#city').value.trim();$('#city').closest('.field').classList.toggle('invalid',!city);if(!city)return;const nextProfile=profile();const profileChanged=Object.keys(nextProfile).some(key=>state.profile[key]!==nextProfile[key]);state.profile=nextProfile;if(profileChanged&&state.selected.length){state.selected=[];state.assessment=[];toast('Garden cleared for your updated profile')}renderPlants();showStep(2)});
$('#recommendations').addEventListener('click',e=>{const b=e.target.closest('.add-plant');if(!b)return;const id=b.dataset.id;normaliseSelection();const selected=state.selected.includes(id);state.selected=selected?state.selected.filter(plantId=>plantId!==id):[...state.selected,id];save();renderPlants()});
$('#clearGarden').addEventListener('click',()=>{state.selected=[];state.assessment=[];save();renderPlants();toast('Garden cleared')});
$('#gardenNext').addEventListener('click',()=>{updateGardenUI();showStep(3)});$('#departure').addEventListener('change',updateDuration);$('#returnDate').addEventListener('change',updateDuration);
$('#balconyPhoto').addEventListener('change',e=>{const file=e.target.files?.[0];if(!file)return;if(file.size>8*1024*1024){toast('Choose a photo under 8 MB');e.target.value='';return}showBalconyPreview(file)});$('#scanBalcony').addEventListener('click',analyzeBalcony);
$('#tripForm').addEventListener('submit',e=>{e.preventDefault();if(!state.selected.length){toast('Add at least one plant first');showStep(2);return}updateDuration();if(state.duration<=0)return;state.departure=$('#departure').value;state.returnDate=$('#returnDate').value;buildResults()});
$$('.step,[data-menu]').forEach(b=>b.addEventListener('click',()=>showStep(+(b.dataset.step||b.dataset.menu))));
$('#gardenShortcut').addEventListener('click',()=>showStep(2));
$('#exploreToggle').addEventListener('click',()=>{state.showAll=!state.showAll;renderPlants();save()});
$$('.foster-option').forEach(b=>b.addEventListener('click',()=>{$$('.foster-option').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.foster=b.dataset.foster;renderPassport();save()}));
$('#copyPassport').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(passportText());$('#copyStatus').textContent='Copied to clipboard';toast('Care brief copied')}catch{$('#copyStatus').textContent='Select and copy the passport text manually.'}});
$('#demoButton').addEventListener('click',loadDemo);$('#startOver').addEventListener('click',()=>{localStorage.removeItem('plantstay-state');location.reload()});
try{const saved=JSON.parse(localStorage.getItem('plantstay-state'));if(saved)Object.assign(state,saved)}catch{}if(!state.user)state.user=makeGuest();$('#anonymousChip').textContent=`Guest gardener · #${state.user.id}`;hydrate();renderPlants();showStep(state.step||1);if(state.step===4&&state.duration&&state.selected.length)buildResults();
